-- SOLO CI: complementa la base financiera aislada; nunca ejecutar en producción.
create schema vault;
create table vault.secrets(id uuid primary key default gen_random_uuid(),secret bytea not null);
create view vault.decrypted_secrets as select id,public.pgp_sym_decrypt(secret,'CI-ONLY-FAKE-KEY') decrypted_secret from vault.secrets;
create function vault.create_secret(new_secret text,new_name text default null,new_description text default '',new_key_id uuid default null) returns uuid language plpgsql as $$declare sid uuid;begin insert into vault.secrets(secret) values(public.pgp_sym_encrypt(new_secret,'CI-ONLY-FAKE-KEY')) returning id into sid;return sid;end;$$;
create function vault.update_secret(secret_id uuid,new_secret text default null,new_name text default null,new_description text default null,new_key_id uuid default null) returns void language sql as $$update vault.secrets set secret=public.pgp_sym_encrypt(new_secret,'CI-ONLY-FAKE-KEY') where id=secret_id$$;
create table public.cc_user_details(user_id uuid primary key,full_name text);
create table public.cc_real_topup_orders(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users,service text not null,amount_pen numeric not null,currency text default 'PEN',provider text default 'LEMON_DALE',status text default 'PENDING',provider_transaction_id text,created_at timestamptz default now(),expires_at timestamptz default now()+interval '30 minutes',verified_at timestamptz,credited_at timestamptz,payment_currency text default 'PEN',payment_amount numeric,quote_rate_pen_per_usdt numeric,quote_source text,quote_valid_until timestamptz);
create table public.cc_manual_recharge_requests(id uuid primary key default gen_random_uuid(),order_id uuid unique references public.cc_real_topup_orders,user_id uuid references auth.users,service text,amount_pen numeric,payer_name text,payer_reference text,status text default 'PENDING',bank_transaction_id text,source_bank text,reviewed_by uuid,reviewed_at timestamptz,created_at timestamptz default now());
create table public.cc_binance_merchant_orders(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users,service text,amount_pen numeric,merchant_trade_no text unique,expected_usdt numeric,prepay_id text,checkout_url text,merchant_id text,status text default 'CREATING',provider_transaction_id text,created_at timestamptz default now(),expires_at timestamptz default now()+interval '10 minutes',credited_at timestamptz);
create table public.cc_binance_merchant_credits(id uuid primary key default gen_random_uuid(),order_id uuid unique references public.cc_binance_merchant_orders,user_id uuid,service text,transaction_id text unique,usdt_paid numeric,amount_pen numeric);
alter table public.cc_real_wallet_ledger add column user_id uuid,add column service text,add column order_id uuid references public.cc_real_topup_orders,add column provider text,add column provider_transaction_id text,add column source_bank text,add column created_at timestamptz default now();
create table cc_internal.cc_verified_payment_receipts(provider_family text,transaction_reference text,source_table text,source_id uuid,user_id uuid,service text,amount_pen numeric,created_at timestamptz default now(),unique(transaction_reference));
create function public.cc_manual_recharge_public_status() returns table(enabled boolean,qr_url text,destination text,message text) language sql as $$select false,null::text,null::text,'Sin autorización de receptor'::text$$;
